package com.campusconnect.enrollment; import org.springframework.data.jpa.repository.JpaRepository; import java.util.List; import java.util.Optional; public interface EnrollmentRepository extends JpaRepository<Enrollment,Long>{ List<Enrollment> findByStudentEmailOrderByEnrolledAtDesc(String email); List<Enrollment> findByCourseId(Long courseId); Optional<Enrollment> findByCourseIdAndStudentEmail(Long courseId,String email); }
